u16 Display24BitsTo16Bits(u32 color24Bytes)
{
	u16 r=(color24Bytes>>16)/255*31;
	u16 g=((color24Bytes&0x00FF00)>>8)/255*63;
	u16 b=((color24Bytes&0x0000FF))/255*31;
	u16 res=(r<<11|g<<5|b);
	return res;
}
